Panel::Panel(std::filesystem::path application,std::filesystem::path data,bool networkAllowed,reader::lifecycle::Tracking tracking,reader::lifecycle::Tracking previewTracking,std::shared_ptr<tomink::IllustrationProvider> images):canvas_(tracking),runtime_(application,data,canvas_,networkAllowed),reply_(std::move(application),std::move(data),previewTracking,std::move(images)),paper_(1632*2160,0xffffffffu){runtime_.start();}
Panel::~Panel(){if(!finish(5000)&&!(runtime_.drained()&&reply_.drained()&&runtime_.unsaved()==0&&!canvas_.unsaved()))std::_Exit(78);}
